const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const N = data[idx++];
const K = data[idx++];

const a = new Array(N);
for (let i = 0; i < N; i++) a[i] = data[idx++];

const b = new Array(N);
for (let i = 0; i < N; i++) b[i] = data[idx++];

let base = 0;
const g = new Array(N);

for (let i = 0; i < N; i++) {
    if (a[i] > b[i]) {
        base += a[i] - b[i];
    }
    g[i] = Math.min(a[i], b[i]);
}

g.sort((x, y) => y - x);

const take = Math.min(K + 1, N);
let extra = 0;

for (let i = 0; i < take; i++) {
    extra += g[i];
}

console.log(base + extra);
